CREATE INDEX idx_applied_ops_command ON Applied_Operations(Command_Name);
CREATE INDEX idx_applied_ops_created_at ON Applied_Operations(Created_At_Ms);
CREATE INDEX idx_applied_ops_status ON Applied_Operations(Status);
CREATE INDEX idx_asig_fecha ON Asignacion_Turnos(Fecha);
CREATE INDEX idx_asig_trab_fecha ON Asignacion_Turnos(ID_Trabajador, Fecha);
CREATE INDEX idx_comandas_mesa_estado ON Comandas(ID_Mesa, Estado);
CREATE INDEX idx_comandas_reserva ON Comandas(ID_Reserva);
CREATE INDEX idx_comandas_trab_apertura ON Comandas(ID_Trabajador, Fecha_Hora_Apertura);
CREATE INDEX idx_cuentas_gastos_fecha ON Cuentas_Gastos(Fecha);
CREATE INDEX idx_cuentas_gastos_proveedor ON Cuentas_Gastos(ID_Proveedor);
CREATE INDEX idx_dc_cocinero_fecha ON Detalle_Comanda(ID_Usuario_Cocinero, Fecha_Hora_Cocina);
CREATE INDEX idx_dc_comanda ON Detalle_Comanda(ID_Comanda);
CREATE INDEX idx_dc_estado_fecha ON Detalle_Comanda(Estado_Cocina, Fecha_Hora_Cocina);
CREATE INDEX idx_dc_producto ON Detalle_Comanda(ID_Producto);
CREATE INDEX idx_facturas_cliente ON Facturas(ID_Cliente);
CREATE INDEX idx_fichajes_user_abierto ON Fichajes(ID_Usuario, Estado);
CREATE INDEX idx_fichajes_user_fecha ON Fichajes(ID_Usuario, Fecha);
CREATE INDEX idx_hp_trab_weekday ON Horario_Predeterminado(ID_Trabajador, Weekday);
CREATE INDEX idx_lineas_pedido_prov_pedido ON Lineas_Pedido_Proveedor(ID_Pedido);
CREATE INDEX idx_lote_consumos_lote ON Lote_Consumos(ID_Lote);
CREATE INDEX idx_lotes_producto_cad ON Lotes_Producto(ID_Producto, Caducidad);
CREATE INDEX idx_lotes_producto_entrada ON Lotes_Producto(ID_Producto, Fecha_Entrada);
CREATE INDEX idx_lotes_producto_stock ON Lotes_Producto(ID_Producto, Stock_Disponible);
CREATE INDEX idx_pago_detalles_detalle ON Pago_Detalles(ID_Detalle);
CREATE INDEX idx_pagos_comanda_fecha ON Pagos(ID_Comanda, Fecha_Hora);
CREATE INDEX idx_pagos_fecha ON Pagos(Fecha_Hora);
CREATE INDEX idx_pagos_trab_cobrador_fecha ON Pagos(ID_Trabajador_Cobrador, Fecha_Hora);
CREATE INDEX idx_pedidos_prov_proveedor ON Pedidos_Proveedor(ID_Proveedor);
CREATE INDEX idx_prod_alerg_alerg ON Producto_Alergenos(ID_Alergeno);
CREATE INDEX idx_prod_alerg_prod ON Producto_Alergenos(ID_Producto);
CREATE INDEX idx_productos_categoria ON Productos(ID_Categoria);
CREATE INDEX idx_productos_proveedor ON Productos(ID_Proveedor);
CREATE INDEX idx_reservas_cliente ON Reservas(ID_Cliente);
CREATE INDEX idx_reservas_mesa_dia_hora ON Reservas(ID_Mesa, Dia_YMD, Hora);
CREATE INDEX idx_tarea_asig_tarea ON Tarea_Asignaciones(ID_Tarea);
CREATE INDEX idx_tarea_asig_trab ON Tarea_Asignaciones(ID_Trabajador, Estado);
CREATE TABLE Alergenos ( ID_Alergeno TEXT PRIMARY KEY, Nombre TEXT NOT NULL UNIQUE, Nombre_Imagen TEXT, Ruta_Imagen TEXT );
CREATE TABLE Applied_Operations ( ID_Applied_Operation INTEGER PRIMARY KEY AUTOINCREMENT, Op_Id TEXT NOT NULL, Command_Name TEXT NOT NULL, Request_Hash TEXT NOT NULL, Device_Id TEXT, Status TEXT NOT NULL DEFAULT 'PROCESSING', Result_Json TEXT, Error_Text TEXT, Created_At_Ms INTEGER NOT NULL, Applied_At_Ms INTEGER, Updated_At_Ms INTEGER NOT NULL, UNIQUE (Op_Id), CHECK (Status IN ('PROCESSING', 'APPLIED', 'FAILED')) );
CREATE TABLE Asignacion_Turnos ( ID_Asignacion TEXT PRIMARY KEY, ID_Trabajador TEXT NOT NULL, Fecha DATE NOT NULL, ID_Turno TEXT NOT NULL, Area TEXT NOT NULL, Hora_Inicio TIME, Hora_Fin TIME, Notas TEXT, FOREIGN KEY (ID_Trabajador) REFERENCES Trabajadores(ID_Trabajador), FOREIGN KEY (ID_Turno) REFERENCES Turnos(ID_Turno) );
CREATE TABLE Business_Settings ( ID INTEGER PRIMARY KEY CHECK (ID = 1), Business_Name TEXT NOT NULL DEFAULT 'TPV', Logo_DataUrl TEXT, Direccion TEXT DEFAULT '', Telefono TEXT DEFAULT '', CIF TEXT DEFAULT '', Mensaje_Footer TEXT DEFAULT '¡Gracias por su visita!', IVA_Percent REAL NOT NULL DEFAULT 10, Updated_At TEXT DEFAULT (datetime('now','localtime')) );
CREATE TABLE Categorias_Producto ( ID_Categoria TEXT PRIMARY KEY, Nombre TEXT NOT NULL UNIQUE, Nombre_Imagen TEXT, Ruta_Imagen TEXT, Vendible INTEGER NOT NULL DEFAULT 1, Pasa_Cocina INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE Clientes ( ID_Cliente TEXT PRIMARY KEY, Nombre TEXT NOT NULL, Telefono TEXT, Email TEXT, Notas TEXT, Total_Gastado REAL NOT NULL DEFAULT 0, Created_At TEXT DEFAULT (datetime('now','localtime')) );
CREATE TABLE Comandas ( ID_Comanda TEXT PRIMARY KEY, ID_Mesa TEXT NOT NULL, ID_Reserva TEXT NULL, ID_Trabajador TEXT NULL, Fecha_Hora_Apertura TEXT NOT NULL, Fecha_Hora_Cierre TEXT NULL, Total_Comanda REAL NOT NULL DEFAULT 0, Estado TEXT NOT NULL DEFAULT 'Abierta', FOREIGN KEY (ID_Mesa) REFERENCES Mesas(ID_Mesa), FOREIGN KEY (ID_Reserva) REFERENCES Reservas(ID_Reserva), FOREIGN KEY (ID_Trabajador) REFERENCES Trabajadores(ID_Trabajador) ON DELETE SET NULL );
CREATE TABLE Contact_Settings ( ID INTEGER PRIMARY KEY CHECK (ID = 1), Recovery_Email TEXT NOT NULL DEFAULT '', Contact_Email TEXT NOT NULL DEFAULT '', Contact_Phone TEXT NOT NULL DEFAULT '', Updated_At TEXT DEFAULT (datetime('now','localtime')) );
CREATE TABLE Cuentas_Gastos ( ID_Gasto TEXT PRIMARY KEY, Fecha DATE NOT NULL, Concepto TEXT NOT NULL, Importe REAL NOT NULL, Tipo_Gasto TEXT NOT NULL, ID_Proveedor TEXT NULL, FOREIGN KEY (ID_Proveedor) REFERENCES Proveedores(ID_Proveedor) ON DELETE SET NULL );
CREATE TABLE Detalle_Comanda ( ID_Detalle TEXT PRIMARY KEY, ID_Comanda TEXT NOT NULL, ID_Producto TEXT NOT NULL, Cantidad REAL NOT NULL, Precio_Unitario REAL NOT NULL, Notas TEXT, Estado_Cocina TEXT DEFAULT 'PENDIENTE', Fecha_Hora_Cocina DATETIME, ID_Usuario_Cocinero TEXT, FOREIGN KEY (ID_Comanda) REFERENCES Comandas(ID_Comanda), FOREIGN KEY (ID_Producto) REFERENCES Productos(ID_Producto) );
CREATE TABLE Email_Settings ( ID INTEGER PRIMARY KEY CHECK (ID = 1), Modo TEXT NOT NULL DEFAULT 'managed' CHECK (Modo IN ('managed', 'smtp')), Smtp_Host TEXT NOT NULL DEFAULT '', Smtp_Port INTEGER NOT NULL DEFAULT 587, Smtp_User TEXT NOT NULL DEFAULT '', Smtp_Password TEXT NOT NULL DEFAULT '', Smtp_From_Email TEXT NOT NULL DEFAULT '', Smtp_From_Name TEXT NOT NULL DEFAULT '', Smtp_Use_Tls INTEGER NOT NULL DEFAULT 1, Updated_At TEXT DEFAULT (datetime('now','localtime')) );
CREATE TABLE Facturas ( ID_Factura TEXT PRIMARY KEY, ID_Comanda TEXT UNIQUE NOT NULL, ID_Cliente TEXT, Fecha_Emision DATETIME NOT NULL, Subtotal REAL NOT NULL, IVA REAL NOT NULL, Total_Pagado REAL NOT NULL, Metodo_Pago TEXT, FOREIGN KEY (ID_Comanda) REFERENCES Comandas(ID_Comanda), FOREIGN KEY (ID_Cliente) REFERENCES Clientes(ID_Cliente) );
CREATE TABLE Fichaje_Dia ( ID_Usuario TEXT NOT NULL, Fecha DATE NOT NULL, Turno_Partido INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (ID_Usuario, Fecha), FOREIGN KEY (ID_Usuario) REFERENCES Usuarios(ID_Usuario) );
CREATE TABLE Fichajes ( ID_Fichaje TEXT PRIMARY KEY, ID_Usuario TEXT NOT NULL, Fecha DATE NOT NULL, Parte INTEGER NOT NULL DEFAULT 1, Hora_Entrada DATETIME, Hora_Salida DATETIME, Estado TEXT DEFAULT 'ABIERTO', Cerrado_Automatico INTEGER DEFAULT 0, Cierre_Motivo TEXT, Incidencia TEXT, UNIQUE(ID_Usuario, Fecha, Parte), FOREIGN KEY (ID_Usuario) REFERENCES Usuarios(ID_Usuario) );
CREATE TABLE Horario_Predeterminado ( ID_Default TEXT PRIMARY KEY, ID_Trabajador TEXT NOT NULL, Weekday INTEGER NOT NULL, Orden INTEGER NOT NULL DEFAULT 1, ID_Turno TEXT NOT NULL, Area TEXT NOT NULL, Hora_Inicio TIME, Hora_Fin TIME, Notas TEXT, FOREIGN KEY (ID_Trabajador) REFERENCES Trabajadores(ID_Trabajador) ON DELETE CASCADE, FOREIGN KEY (ID_Turno) REFERENCES Turnos(ID_Turno), UNIQUE (ID_Trabajador, Weekday, Orden) );
CREATE TABLE Lineas_Pedido_Proveedor ( ID_Linea TEXT PRIMARY KEY, ID_Pedido TEXT NOT NULL, Nombre_Producto TEXT NOT NULL, Cantidad REAL NOT NULL DEFAULT 1, Precio_Unitario REAL, Unidad TEXT, FOREIGN KEY (ID_Pedido) REFERENCES Pedidos_Proveedor(ID_Pedido) ON DELETE CASCADE );
CREATE TABLE Lote_Consumos ( ID_Detalle TEXT NOT NULL, ID_Lote TEXT NOT NULL, Cantidad REAL NOT NULL, PRIMARY KEY (ID_Detalle, ID_Lote), FOREIGN KEY (ID_Detalle) REFERENCES Detalle_Comanda(ID_Detalle) ON DELETE CASCADE, FOREIGN KEY (ID_Lote) REFERENCES Lotes_Producto(ID_Lote), CHECK (Cantidad > 0) );
CREATE TABLE Lotes_Producto ( ID_Lote TEXT PRIMARY KEY, ID_Producto TEXT NOT NULL, Codigo_Lote TEXT NOT NULL, Fecha_Entrada DATETIME NOT NULL DEFAULT (datetime('now','localtime')), Caducidad DATE, Cantidad_Inicial REAL NOT NULL DEFAULT 0, Stock_Disponible REAL NOT NULL DEFAULT 0, Coste_Unitario REAL, ID_Proveedor TEXT, Notas TEXT, FOREIGN KEY (ID_Producto) REFERENCES Productos(ID_Producto) ON DELETE CASCADE, FOREIGN KEY (ID_Proveedor) REFERENCES Proveedores(ID_Proveedor), UNIQUE (ID_Producto, Codigo_Lote), CHECK (Cantidad_Inicial >= 0), CHECK (Stock_Disponible >= 0) );
CREATE TABLE Mesas ( ID_Mesa TEXT PRIMARY KEY, ID_Zona TEXT NOT NULL, Numero_Mesa TEXT NOT NULL, Capacidad INTEGER NOT NULL, Ubicacion_X INTEGER NOT NULL, Ubicacion_Y INTEGER NOT NULL, Shape TEXT NOT NULL, Width INTEGER NOT NULL, Height INTEGER NOT NULL, Radius INTEGER, Updated_At DATETIME, Es_Sistema INTEGER NOT NULL DEFAULT 0, UNIQUE (ID_Zona, Numero_Mesa), FOREIGN KEY (ID_Zona) REFERENCES Zonas(ID_Zona) ON DELETE CASCADE );
CREATE TABLE Pago_Detalles ( ID_Pago TEXT NOT NULL, ID_Detalle TEXT NOT NULL, PRIMARY KEY (ID_Pago, ID_Detalle), FOREIGN KEY (ID_Pago) REFERENCES Pagos(ID_Pago), FOREIGN KEY (ID_Detalle) REFERENCES Detalle_Comanda(ID_Detalle) );
CREATE TABLE Pagos ( ID_Pago TEXT PRIMARY KEY, ID_Comanda TEXT NOT NULL, Fecha_Hora DATETIME NOT NULL, Metodo_Pago TEXT NOT NULL, Importe_Total REAL NOT NULL, Tipo TEXT NOT NULL, ID_Usuario_Cobrador TEXT, ID_Trabajador_Cobrador TEXT, FOREIGN KEY (ID_Comanda) REFERENCES Comandas(ID_Comanda) ON DELETE CASCADE, FOREIGN KEY (ID_Usuario_Cobrador) REFERENCES Usuarios(ID_Usuario) ON DELETE SET NULL, FOREIGN KEY (ID_Trabajador_Cobrador) REFERENCES Trabajadores(ID_Trabajador) ON DELETE SET NULL );
CREATE TABLE Pedidos_Proveedor ( ID_Pedido TEXT PRIMARY KEY, ID_Proveedor TEXT, Email_Destino TEXT, Estado TEXT NOT NULL DEFAULT 'borrador', Fecha_Creacion TEXT NOT NULL DEFAULT (datetime('now','localtime')), Fecha_Envio TEXT, Notas TEXT, FOREIGN KEY (ID_Proveedor) REFERENCES Proveedores(ID_Proveedor) ON DELETE SET NULL, CHECK (Estado IN ('borrador', 'enviado', 'cancelado')) );
CREATE TABLE Producto_Alergenos ( ID_Producto TEXT NOT NULL, ID_Alergeno TEXT NOT NULL, PRIMARY KEY (ID_Producto, ID_Alergeno), FOREIGN KEY (ID_Producto) REFERENCES Productos(ID_Producto) ON DELETE CASCADE, FOREIGN KEY (ID_Alergeno) REFERENCES Alergenos(ID_Alergeno) ON DELETE CASCADE );
CREATE TABLE Productos ( ID_Producto TEXT PRIMARY KEY, ID_Categoria TEXT NOT NULL, ID_Proveedor TEXT, Nombre TEXT NOT NULL UNIQUE, Precio_Venta REAL, Stock_Minimo REAL DEFAULT 0, Unidad_Medida TEXT, Nombre_Imagen TEXT, Ruta_Imagen TEXT, Cantidad_Pedido_Esperada REAL, FOREIGN KEY (ID_Categoria) REFERENCES Categorias_Producto(ID_Categoria), FOREIGN KEY (ID_Proveedor) REFERENCES Proveedores(ID_Proveedor) );
CREATE TABLE Proveedores ( ID_Proveedor TEXT PRIMARY KEY, Nombre_Empresa TEXT NOT NULL, Contacto TEXT, Telefono TEXT, Email TEXT UNIQUE, CIF TEXT UNIQUE, Informacion_adicional TEXT, Nombre_Imagen TEXT, Ruta_Imagen TEXT );
CREATE TABLE Reservas ( ID_Reserva TEXT PRIMARY KEY, ID_Cliente TEXT NOT NULL, ID_Mesa TEXT NOT NULL, Dia_YMD TEXT NOT NULL, Hora TEXT NOT NULL, Turno TEXT NOT NULL, Comensales INTEGER NOT NULL DEFAULT 1, Nota TEXT, Estado TEXT NOT NULL DEFAULT 'ACTIVA', Created_At TEXT DEFAULT (datetime('now','localtime')), FOREIGN KEY (ID_Cliente) REFERENCES Clientes(ID_Cliente), FOREIGN KEY (ID_Mesa) REFERENCES Mesas(ID_Mesa) );
CREATE TABLE Roles ( ID_Rol TEXT PRIMARY KEY, Nombre_Rol TEXT NOT NULL UNIQUE );
CREATE TABLE Tarea_Asignaciones ( ID_Tarea TEXT NOT NULL, ID_Trabajador TEXT NOT NULL, Asignada_At DATETIME NOT NULL DEFAULT (datetime('now','localtime')), Estado TEXT NOT NULL DEFAULT 'PENDIENTE', Finalizada_At DATETIME, PRIMARY KEY (ID_Tarea, ID_Trabajador), FOREIGN KEY (ID_Tarea) REFERENCES Tareas(ID_Tarea) ON DELETE CASCADE, FOREIGN KEY (ID_Trabajador) REFERENCES Trabajadores(ID_Trabajador) ON DELETE CASCADE );
CREATE TABLE Tareas ( ID_Tarea TEXT PRIMARY KEY, Titulo TEXT NOT NULL, Descripcion TEXT, Fecha_Creacion DATETIME NOT NULL DEFAULT (datetime('now','localtime')), Fecha_Limite DATE, Estado TEXT NOT NULL DEFAULT 'ABIERTA' );
CREATE TABLE Ticket_Settings ( ID INTEGER PRIMARY KEY CHECK (ID = 1), Show_Logo INTEGER NOT NULL DEFAULT 1, Show_BusinessName INTEGER NOT NULL DEFAULT 1, Show_Address INTEGER NOT NULL DEFAULT 1, Show_Phone INTEGER NOT NULL DEFAULT 1, Show_CIF INTEGER NOT NULL DEFAULT 1, Show_DateTime INTEGER NOT NULL DEFAULT 1, Show_LineItems INTEGER NOT NULL DEFAULT 1, Show_BaseAndIVA INTEGER NOT NULL DEFAULT 1, Show_Total INTEGER NOT NULL DEFAULT 1, Show_FooterMessage INTEGER NOT NULL DEFAULT 1, Paper_Width_Mm INTEGER NOT NULL DEFAULT 80, Paper_Dpi INTEGER NOT NULL DEFAULT 203, Chars_Per_Line INTEGER NOT NULL DEFAULT 42, Margin_Top_Mm REAL NOT NULL DEFAULT 0, Margin_Bottom_Mm REAL NOT NULL DEFAULT 0, Margin_Left_Mm REAL NOT NULL DEFAULT 0, Margin_Right_Mm REAL NOT NULL DEFAULT 0, Font_Scale REAL NOT NULL DEFAULT 1.0, Updated_At TEXT DEFAULT (datetime('now','localtime')), CHECK (Paper_Width_Mm IN (58, 80, 112)), CHECK (Paper_Dpi IN (203, 300)), CHECK (Chars_Per_Line >= 20 AND Chars_Per_Line <= 80), CHECK (Font_Scale >= 0.5 AND Font_Scale <= 2.0) );
CREATE TABLE Trabajadores ( ID_Trabajador TEXT PRIMARY KEY, ID_Usuario TEXT UNIQUE NOT NULL, DNI TEXT UNIQUE, Telefono TEXT, Puesto TEXT, IBAN TEXT, Numero_Seguridad_Social TEXT UNIQUE, Fecha_Inicio_Contrato DATE, Fecha_Fin_Contrato DATE, FOREIGN KEY (ID_Usuario) REFERENCES Usuarios(ID_Usuario) );
CREATE TABLE Turnos ( ID_Turno TEXT PRIMARY KEY, Nombre_Turno TEXT NOT NULL UNIQUE );
CREATE TABLE Usuarios ( ID_Usuario TEXT PRIMARY KEY, ID_Rol TEXT NOT NULL, Email TEXT NOT NULL UNIQUE, Password_Hash TEXT NOT NULL, Nombre TEXT NOT NULL, Apellido TEXT, Estado TEXT DEFAULT 'Activo', Requiere_Setup INTEGER DEFAULT 0, FOREIGN KEY (ID_Rol) REFERENCES Roles(ID_Rol) );
CREATE TABLE Zonas ( ID_Zona TEXT PRIMARY KEY, Nombre_Zona TEXT NOT NULL UNIQUE, Room_Points TEXT NOT NULL DEFAULT '[]', Updated_At DATETIME );
CREATE VIEW v_inventario_producto_stock AS WITH agg AS ( SELECT ID_Producto, COALESCE(SUM(Stock_Disponible), 0) AS Stock_Actual, -- Caducidad mas proxima = MIN de las caducidades de lotes con stock (MIN ignora NULLs). MIN(CASE WHEN COALESCE(Stock_Disponible, 0) > 0 THEN Caducidad END) AS Caducidad_Proxima FROM Lotes_Producto GROUP BY ID_Producto ), lote_fefo AS ( SELECT ID_Producto, Codigo_Lote FROM ( SELECT ID_Producto, Codigo_Lote, ROW_NUMBER() OVER ( PARTITION BY ID_Producto ORDER BY CASE WHEN Caducidad IS NULL THEN 1 ELSE 0 END, date(Caducidad) ASC, datetime(Fecha_Entrada) ASC, ID_Lote ASC ) AS rn FROM Lotes_Producto WHERE COALESCE(Stock_Disponible, 0) > 0 ) WHERE rn = 1 ) SELECT p.ID_Producto, COALESCE(a.Stock_Actual, 0) AS Stock_Actual, a.Caducidad_Proxima AS Caducidad_Proxima, f.Codigo_Lote AS Lote_Proximo FROM Productos p LEFT JOIN agg a ON a.ID_Producto = p.ID_Producto LEFT JOIN lote_fefo f ON f.ID_Producto = p.ID_Producto;
